fn extract_state_key(expr: &Expr, _component: &Component) -> Option<String> {
    if let Expr::Ident(ident) = expr {
        return Some(ident.sym.to_string());
    } else if let Expr::Member(member_expr) = expr {
        let mut current: &Expr = &member_expr.obj;
        while let Expr::Member(m) = current {
            current = &m.obj;
        }
        if let Expr::Ident(ident) = current {
            return Some(ident.sym.to_string());
        }
    }
    None
}
